"""Independent 9709 S1 teaching, examples and complete-answer spread checks."""
from fractions import Fraction as F
from statistics import median
import sympy as s
from s1_representation_teaching import stem,table

lessons,questions,models=[],[],[]
def tex(v):return s.latex(s.Rational(v.numerator,v.denominator) if isinstance(v,F) else s.sympify(v))
def math(v):return r'\('+tex(v)+r'\)'
def data(a):return ', '.join(str(v) for v in a)
def picture(name,alt):return '<p><img src="/assets/original/s1-variation/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,title,summary,ideas,mistakes,examples):
 lessons.append(dict(key=key,id='orig_9709_s1_var_'+key,title=title,summary=summary,objective=summary,before='<p>Use exact totals, order raw observations, and distinguish a frequency from a measurement. Review Measures of central tendency if you need to recover a mean or decode an origin.</p>',ideas=ideas,method='<ol><li>Identify whether the observations are raw, grouped or coded.</li><li>Recover the count, first total and square-total on one consistent scale.</li><li>Find the requested spread without premature rounding.</li><li>Restore all original conditions and give every valid result.</li></ol>',mistakes=mistakes,examples=examples))

lesson('raw_moments','Range, quartiles and raw-data variance',
 'Use a centre and a spread together, distinguishing the middle half from squared deviations about the mean.',
 r'''<h3>A centre alone does not describe a distribution</h3><p>Two samples can have the same mean and very different variation. The range is maximum minus minimum and uses only the two extremes. The interquartile range is \(Q_3-Q_1\), measuring the span of the middle half. It is less affected by the size of an extreme value than the range.</p>'''+picture('equal-centres','Two samples with mean 8 have different ranges and standard deviations')+r'''
 <h3>State the raw-data quartile convention</h3><p>Order every observation, including repetitions. Here, take the medians of the lower and upper halves, excluding the overall median for an odd count. This is the chapter convention, not a claim that every software package uses identical quartile positions.</p>
 <h3>Variance uses all deviations from the mean</h3>\[\sigma^2=\frac{\sum(x-\bar{x})^2}{n}.\]\[\sigma^2=\frac{\sum x^2}{n}-\bar{x}^{\,2},\qquad\sigma=\sqrt{\sigma^2}.\]<p>Use divisor n for descriptive spread here. Variance has squared units; SD has the same units as the observations. A negative calculated variance signals an error or inconsistent summaries. SD is zero exactly when all observations are equal.</p>
 <h3>Changing the reference value does not erase spread</h3>\[\begin{aligned}\sum(x-a)^2&=\sum(x-\bar{x})^2\\&\quad+n(a-\bar{x})^2.\end{aligned}\]<p>The square-total about a reference is smallest at the mean. A sum of squared deviations and the square of a sum are different quantities.</p>''',
 ['Do not report a quartile position as a data value.','Use n, not n−1, for these descriptive summaries.','Take the non-negative square root for SD.','Equal means do not imply equal spreads.'],[
 ex('Same mean, different consistency','<p>Compare A: 4, 6, 8, 10, 12 and B: 0, 4, 8, 12, 16. Find their means, ranges and variances.</p>',r'<p>Both means are 8. Their ranges are 8 and 16.</p>\[\sigma_A^2=\frac{16+4+0+4+16}{5}=8.\]\[\begin{aligned}\sigma_B^2&=\frac{64+16+0+16+64}{5}\\&=32.\end{aligned}\]<p>A has less variation. This is a comparison of spread, not a claim that its centre is smaller.</p>','VAR-CENTRES'),
 ex('Range and IQR use different parts of the data','<p>Find the range and IQR of 2, 3, 4, 6, 6, 7, 10, 30, using medians of halves.</p>',r'\[\begin{aligned}\text{range}&=30-2=28,\\Q_1&=\frac{3+4}{2}=\frac72,\\Q_3&=\frac{7+10}{2}=\frac{17}{2},\\\text{IQR}&=5.\end{aligned}\]<p>The large final observation stretches the range; its exact size does not enter either quartile here.</p>','VAR-QUARTILES'),
 ex('Moments recover the centred square-total',r'<p>Five observations have \(\sum x=40\), \(\sum x^2=350\). Find their mean, centred square-total and SD.</p>',r'\[\begin{aligned}\bar{x}&=8,\\\sum(x-8)^2&=350-5(8^2)=30,\\\sigma&=\sqrt{30/5}=\sqrt6.\end{aligned}\]<p>Divide the centred total by the count before taking the square root.</p>','VAR-MOMENTS'),
 ex('The best reference for squared deviations',r'<p>For 3, 7, 9, 13, find the real a minimising \(\sum(x-a)^2\), and its minimum.</p>',r'<p>The mean is 8 and the centred square-total is 52.</p>\[\sum(x-a)^2=52+4(a-8)^2.\]<p>The minimum is 52, attained only at a=8. The variance is \(52/4=13\); it is not zero.</p>','VAR-REFERENCE')])

lesson('coded_totals','Coded totals, origins and scale changes',
 'Recover original spread from coding, and handle translations, negative scales and a second reference correctly.',
 r'''<h3>A translation leaves spread unchanged</h3><p>For \(u=x-c\),</p>\[\bar{x}=c+\frac{\sum u}{n}.\]\[\sigma_x^2=\frac{\sum u^2}{n}-\left(\frac{\sum u}{n}\right)^2.\]<p>Squaring each coded value before adding usually avoids large raw totals. Do not assume the coded mean is zero.</p>
 <h3>Decode a scale in the correct direction</h3><p>If \(u=(x-a)/b\), write \(x=a+bu\), with \(b\ne0\).</p>\[\begin{aligned}\bar{x}&=a+b\bar{u},\\\sigma_x^2&=b^2\sigma_u^2,\\\sigma_x&=|b|\sigma_u.\end{aligned}\]<p>A negative multiplier reverses order, but SD remains non-negative. Translations do not change range or IQR; scaling multiplies each by the absolute multiplier.</p>
 <h3>Moving from one origin to another</h3><p>Write \(D_c=\sum(x-c)\), \(E_c=\sum(x-c)^2\), and \(h=d-c\). Expanding each square gives</p>\[\begin{aligned}D_d&=D_c-nh,\\E_d&=E_c-2hD_c+nh^2.\end{aligned}\]<p>The variance calculated from either pair must agree.</p>
 <h3>Recover the original totals when needed</h3>\[\begin{aligned}\sum x&=na+b\sum u,\\\sum x^2&=na^2+2ab\sum u+b^2\sum u^2.\end{aligned}\]<p>Keep the cross-term: a square of a shifted variable is not just the original square plus a constant.</p>
 <h3>Finding an unknown calibration</h3><p>For y=px+q with positive original SD, the new SD fixes |p|. Test both signs of p and use the mean to recover q:</p>\[\begin{aligned}|p|&=\sigma_y/\sigma_x,\\q&=\bar{y}-p\bar{x}.\end{aligned}\]<p>If the largest original reading becomes the smallest transformed reading, select p&lt;0. If the original SD is zero, all readings coincide and this ratio cannot be used.</p>''',
 ['The coded sum need not vanish.','A negative scale does not give negative SD.','Keep the cross-term when moving origins.','Decode both original totals before mixing scales.'],[
 ex('A convenient origin keeps the arithmetic small',r'<p>For \(u=x-100\), n=6, \(\sum u=9\), \(\sum u^2=39\). Find the original mean and SD.</p>',r'\[\begin{aligned}\bar{x}&=100+\frac96=\frac{203}{2},\\\sigma_x^2&=\frac{39}{6}-\left(\frac96\right)^2=\frac{17}{4},\\\sigma_x&=\frac{\sqrt{17}}2.\end{aligned}\]','VAR-TRANSLATE'),
 ex('Undo a negative scale',r'<p>For \(u=(x-30)/(-4)\), n=8, \(\sum u=12\), \(\sum u^2=30\). Find the original mean and variance.</p>',r'\[\begin{aligned}\bar{u}&=\frac32,\\\sigma_u^2&=\frac{30}{8}-\frac94=\frac32,\\\bar{x}&=30-4\left(\frac32\right)=24,\\\sigma_x^2&=16\left(\frac32\right)=24.\end{aligned}\]<p>The SD is \(2\sqrt6\), not its negative.</p>','VAR-NEGATIVE-SCALE'),
 ex('Use a second origin without the raw data',r'<p>For five readings, \(\sum(x-20)=-10\), \(\sum(x-20)^2=46\). Find both totals about 25.</p>',r'\[\sum(x-25)=-10-25=-35.\]\[\begin{aligned}\sum(x-25)^2&=46+100+125\\&=271.\end{aligned}\]<p>Both origins give variance \(26/5\). The changed square-total alone does not indicate changed spread.</p>','VAR-RECODE'),
 ex('Decode a square-total including its cross-term',r'<p>For \(u=(x-10)/2\), n=4, \(\sum u=6\), \(\sum u^2=14\). Find \(\sum x\), \(\sum x^2\) and the variance.</p>',r'\[\begin{aligned}\sum x&=4(10)+2(6)=52,\\\sum x^2&=4(100)+4(10)(6)\\&\quad+4(14)\\&=696,\\\sigma_x^2&=696/4-13^2=5.\end{aligned}\]','VAR-RAW-TOTALS')])

lesson('reconstruction','Reverse moments, feasible summaries and all valid branches',
 'Use variance to reconstruct missing information, retaining every feasible count or sign before applying extra conditions.',
 r'''<h3>An unknown count occurs more than once</h3><p>If the sum is S, square-total T and variance v, then</p>\[vn^2-Tn+S^2=0.\]<p>Solve for every positive integer count. Check n=1 separately when v is positive, because one observation cannot have positive variance. Real-valued observations do not have to be integer counts themselves.</p>
 <h3>Recovering a mean can introduce two signs</h3>\[\bar{x}^{\,2}=\frac{T}{n}-v.\]<p>Both square roots may be possible. An original condition such as a positive mean can select one; do not silently add it.</p>
 <h3>Check consistency before taking a square root</h3>\[\sum x^2\ge\frac{(\sum x)^2}{n}.\]<p>This follows from non-negative variance. Equality means all values equal the mean. For n≥2 real observations, this inequality is also sufficient; extra restrictions such as non-negative integers may impose more conditions.</p>
 <h3>A hidden reference must satisfy both moments</h3><p>Recover c from \(\sum(x-c)=n(\bar{x}-c)\), then use the squared coded total for spread. Recheck both original equations. A quadratic candidate is a possibility to test, not an automatically valid answer.</p>''',
 ['A positive quadratic root need not be an integer count.','Do not drop the negative mean without a stated condition.','A negative implied variance is not a real SD.','Keep all feasible branches before using extra information.'],[
 ex('Two counts can fit one pair of moments',r'<p>Real observations have \(\sum x=20\), \(\sum x^2=120\) and variance 8. Find all possible counts. Then use \(\bar{x}>3\).</p>',r'\[8n^2-120n+400=0.\]\[8(n-5)(n-10)=0.\]<p>The possibilities are n=5 and n=10, with means 4 and 2. Both moments are feasible for real observations; the extra condition selects n=5.</p>','VAR-TWO-COUNTS'),
 ex('A square-total does not determine the sign of the mean',r'<p>Six real observations have square-total 150 and variance 9. Find all means, then select the positive mean and its sum.</p>',r'\[\bar{x}^{\,2}=150/6-9=16.\]<p>The means are −4 and 4. The positive choice is 4, giving sum 24. It would be incomplete to give only 4 before using the extra condition.</p>','VAR-TWO-MEANS'),
 ex('Recover an unrecorded origin',r'<p>Five observations have mean 12, \(\sum(x-c)=-15\), \(\sum(x-c)^2=80\). Find c and the SD.</p>',r'\[5(12-c)=-15\quad\Rightarrow\quad c=15.\]\[\sigma^2=80/5-(-15/5)^2=7.\]<p>The SD is \(\sqrt7\). The negative coded mean describes the origin, not a negative spread.</p>','VAR-HIDDEN-ORIGIN'),
 ex('Reject an impossible summary',r'<p>A report claims n=6, \(\sum x=30\), \(\sum x^2=140\). Explain the contradiction and find the smallest feasible square-total.</p>',r'\[\sigma^2=140/6-5^2=-5/3.\]<p>A real data set cannot have negative variance.</p>\[\sum x^2\ge30^2/6=150.\]<p>The minimum 150 is attained when all six observations equal 5.</p>','VAR-IMPOSSIBLE')])

lesson('changes_combining','Changed records and pooled variation',
 'Update complete moments when records change, and retain between-group variation when combining two samples.',
 r'''<h3>Replacing a record changes two totals</h3><p>If a recorded value r should have been t,</p>\[\begin{aligned}S_{\rm new}&=S-r+t,\\T_{\rm new}&=T-r^2+t^2.\end{aligned}\]<p>The count is unchanged. Adding or removing a record also changes n. Adding the square of the correction is not the same as replacing the erroneous square.</p>
 <h3>Combine at most two groups through totals</h3>\[\begin{aligned}S_i&=n_i\bar{x}_i,\\T_i&=n_i(\sigma_i^2+\bar{x}_i^{\,2}).\end{aligned}\]<p>Add counts, sums and square-totals, then recompute the pooled variance. First decode any incompatible origins or units.</p>'''+picture('pooled-spread','Within-group variation and differences between group means both contribute to pooled spread')+r'''
 <h3>Differences between means add spread</h3><p>The pooled variance includes both within-group variance and deviations of the group means from the pooled mean. Averaging SDs ignores that second contribution. Combining observed groups differs from adding independent random variables.</p>
 <h3>Subtract a known group to recover a missing one</h3><p>Subtract its count, sum and square-total from the combined values. A recovered negative variance or non-positive count is a signal to recheck the data or interpretation.</p>
 <h3>Adding a value can leave the spread unchanged</h3><p>For n observations with mean μ and variance v, add one value z. Reconstructing both moments gives</p>\[\begin{aligned}v_{\rm new}&=\frac{n}{n+1}v\\&\quad+\frac{n}{(n+1)^2}(z-\mu)^2.\end{aligned}\]<p>Thus unchanged SD requires \((z-\mu)^2=(n+1)v/n\). Retain both signs when v&gt;0; v=0 gives only z=μ.</p>
 <h3>Symmetric changes preserve the mean</h3><p>Replacing μ−d and μ+d by μ−d−t and μ+d+t keeps their sum fixed. For d≥0 and t≥0 the variance becomes</p>\[v_{\rm new}=v+\frac{4dt+2t^2}{n}.\]<p>To impose an SD bound, square a non-negative bound first, solve the variance inequality, and intersect with the original t-domain.</p>''',
 ['Replace r² by t², not by (t−r)².','After removal, the denominator changes as well as the totals.','Do not average group SDs.','Recover a missing group through totals, not subtraction of variances.'],[
 ex('Correct the observation and its square',r'<p>Five readings have sum 60 and square-total 760. One reading 8 should be 13. Find the corrected mean and SD.</p>',r'\[\begin{aligned}S_{\rm new}&=60-8+13=65,\\T_{\rm new}&=760-64+169=865,\\\bar{x}_{\rm new}&=13,\\\sigma_{\rm new}&=\sqrt{865/5-169}=2.\end{aligned}\]','VAR-CORRECTION'),
 ex('Removal changes the divisor',r'<p>Six readings have sum 48 and square-total 420. Remove one reading of 6. Find the remaining mean and variance.</p>',r'\[\begin{aligned}n_{\rm new}&=5,\\S_{\rm new}&=42,\\T_{\rm new}&=384,\\\bar{x}_{\rm new}&=42/5,\\\sigma_{\rm new}^2&=384/5-(42/5)^2\\&=156/25.\end{aligned}\]','VAR-REMOVE'),
 ex('Group means contribute to pooled variation',r'<p>A has n=4, mean 8, SD 2. B has n=6, mean 13, SD 1. Find the combined mean and variance, using descriptive SDs.</p>',r'\[\begin{aligned}S&=32+78=110,\\T&=4(64+4)+6(169+1)\\&=1292,\\\bar{x}&=11,\\\sigma^2&=1292/10-121=41/5.\end{aligned}\]<p>The pooled SD is larger than either group SD because the centres differ.</p>','VAR-POOL'),
 ex('Recover the missing group',r'<p>Ten observations have mean 12 and SD 3. Four of them form group A, with mean 9 and SD 2. Find the count, mean and variance of the other group.</p>',r'\[\begin{aligned}n_B&=6,\\S_B&=120-36=84,\\T_B&=10(9+144)-4(4+81)\\&=1190,\\\bar{x}_B&=14,\\\sigma_B^2&=1190/6-196=7/3.\end{aligned}\]','VAR-MISSING-GROUP')])

lesson('frequency_synthesis','Frequency models, percentiles and multi-step spread problems',
 'Distinguish exact frequency moments, grouped estimates, interpolated percentiles and reconstructed observations.',
 r'''<h3>Frequencies count repetitions</h3>\[\begin{aligned}n&=\sum f,\\\bar{x}&=\frac{\sum fx}{\sum f},\\\sigma^2&=\frac{\sum fx^2}{\sum f}-\bar{x}^{\,2}.\end{aligned}\]<p>Square each measurement, then weight it by frequency. Squaring the frequency-weighted value gives the wrong second moment.</p>
 <h3>Midpoints define an estimating model</h3><p>For grouped data replace x by the class midpoint. Use frequencies as weights, even for unequal-width classes. Frequency density is a histogram height, not a replacement for frequency in these moment formulas. Grouped mean and SD estimate the unknown raw-data statistics.</p>
 <h3>A percentile is a value, not a cumulative count</h3><p>For cumulative proportion p, locate pN and interpolate within its class, assuming uniform within-class spread:</p>\[\widehat{x}_p=L+\frac{pN-C}{f}\,w.\]<p>For the IQR find both quartiles and subtract. To find a value exceeded by k observations, use cumulative count N−k, not k.</p>'''+picture('percentiles','Quartiles are read as measurement values at cumulative counts N/4 and 3N/4')+r'''
 <h3>Two missing values require independent conditions</h3><p>A mean gives their sum. Variance supplies a square-total. Use both, keep the requested ordering, and substitute the recovered pair into the original totals. Complete final answers accompany, rather than replace, written reasoning.</p>''',
 ['Use fx², not (fx)², for the second moment.','Weight grouped moments by frequency, not density.','Subtract measurement quartiles, not their cumulative ranks.','Recover both missing observations and retain their specified order.'],[
 ex('A discrete table gives exact moments',table(['Value','Frequency'],[[1,1],[3,2],[5,3]])+'<p>Find the mean and variance.</p>',r'\[\begin{aligned}n&=6,\\\sum fx&=22,\\\sum fx^2&=94,\\\bar{x}&=11/3,\\\sigma^2&=94/6-(11/3)^2\\&=20/9.\end{aligned}\]','VAR-FREQUENCY'),
 ex('Unequal widths do not change the moment weights',table(['Class','Frequency'],[['0 ≤ x < 4',4],['4 ≤ x < 10',9],['10 ≤ x < 20',5]])+'<p>Estimate the mean and SD using class midpoints.</p>',r'<p>Use midpoints 2, 7, 15 and frequencies 4, 9, 5.</p>\[\begin{aligned}\sum fm&=146,\\\sum fm^2&=1582,\\\bar{x}&\approx73/9,\\\sigma&\approx\sqrt{1790}/9.\end{aligned}\]<p>These are exact expressions for the midpoint model, but estimates for the unknown raw observations.</p>','VAR-GROUPED'),
 ex('Read two quartiles and a percentile',table(['Boundary','Cumulative frequency'],[[0,0],[10,8],[30,32],[50,40]])+'<p>Assume uniform spread within each class. Estimate the IQR and the 90th percentile.</p>',r'\[\begin{aligned}Q_1&=10+\frac{10-8}{24}(20)=35/3,\\Q_3&=10+\frac{30-8}{24}(20)=85/3,\\\text{IQR}&=50/3,\\P_{90}&=30+\frac{36-32}{8}(20)=40.\end{aligned}\]<p>The cumulative targets 10, 30 and 36 are ranks, not measurement values.</p>','VAR-PERCENTILES'),
 ex('A variance supplies a second missing-value equation',r'<p>Add a&lt;b to 2, 4, 5, 7. The six observations have mean 6 and variance 7. Find a and b.</p>',r'\[\begin{aligned}a+b&=36-18=18,\\a^2+b^2&=6(7+36)-94=164.\end{aligned}\]\[a^2+(18-a)^2=164.\]<p>The roots are 8 and 10, so \((a,b)=(8,10)\). Their order and both original moments are satisfied.</p>','VAR-MISSING-PAIR')])

def field(key,label,kind,value,**extra):return dict(key=key,label=label,type=kind,expected=str(value),**extra)
def aset(a):return '{'+','.join(str(v) for v in a)+'}'
def show(f):
 v=f['expected']
 if f['type']=='choice':return f['options'][v]
 if f['type']=='set':return r'\(\{'+', '.join(tex(a) for a in v.strip('{}').split(','))+r'\}\)'
 return math(v)
def quick(topic,family,v,title,prompt,fields,explanation,model):
 uid=f'M4U-9709-S1-VAR-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+show(f)+'</p>' for f in fields)
 questions.append(dict(id=uid,family_uid=f'M4U-9709-S1-VAR-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html='<p>'+explanation+'</p><h4>Complete answers</h4>'+answer,hint_html='<p>Keep exact totals. Check the count, coding direction, all valid branches and the original data restrictions.</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))
def moments(a):
 n=len(a);mu=F(sum(a),n);var=F(sum(x*x for x in a),n)-mu*mu
 return mu,var
def sqrt(v):return s.sqrt(s.Rational(v.numerator,v.denominator))

for v in range(2):
 a=[1,3,4,6,6] if v==0 else [2,2,4,6,6];mu,var=moments(a)
 quick('raw_moments',1,v,'All raw-data moments','<p>For '+data(a)+', give the exact mean, descriptive variance and SD.</p>',[field('mean','Mean','number',mu),field('variance','Descriptive variance','number',var),field('sd','Standard deviation','number',sqrt(var))],'The square-total uses each individual square. Divide by the number of observations and take the non-negative root.',dict(kind='raw',data=a))
 a=[1,2,3,4,6,8,9,10,17] if v==0 else [2,4,4,5,7,8,12,18];n=len(a);q1=F(median(a[:n//2]));q3=F(median(a[(n+1)//2:]));diagram=stem(a)
 quick('raw_moments',2,v,'Quartiles refer to observed values',diagram+'<p>Use medians of halves, excluding the overall median when the count is odd. Give the range, both quartiles and IQR.</p>',[field('range','Range','number',max(a)-min(a)),field('q1','Lower quartile Q1','number',q1),field('q3','Upper quartile Q3','number',q3),field('iqr','Interquartile range','number',q3-q1)],'Count every leaf including repetitions, split at the median using the stated convention, then subtract the quartile values.',dict(kind='quartiles',data=a))
 a,b=([4,6,8,10,12],[0,4,8,12,16]) if v==0 else ([2,5,8,11,14],[6,7,8,9,10]);va,vb=moments(a)[1],moments(b)[1]
 quick('raw_moments',3,v,'Equal centres do not imply equal spreads','<p>A: '+data(a)+'. B: '+data(b)+'. Both means are 8. Give each variance and choose the sample with less variation.</p>',[field('va','Variance of A','number',va),field('vb','Variance of B','number',vb),field('choice','Less variable sample','choice','A' if v==0 else 'B',options={'A':'Sample A','B':'Sample B','C':'Equal variation because their means are equal'})],'Compare spread around the common mean. The shared centre is not evidence of equal variability.',dict(kind='compare',a=a,b=b))
 a=[3,7,9,13] if v==0 else [1,5,9,13];mu,var=moments(a)
 quick('raw_moments',4,v,'The least square-total is not necessarily zero','<p>For '+data(a)+r', find the least value of \(\sum(x-c)^2\), its minimising reference c, and the descriptive variance.</p>',[field('minimum','Least squared-deviation total','number',len(a)*var),field('origin','Minimising reference c','number',mu),field('variance','Descriptive variance','number',var)],'Complete the square in c. The mean minimises the total, but variation among unequal observations remains.',dict(kind='reference',data=a))

 n,D,E,c=(6,9,39,100) if v==0 else (8,-12,34,50);mu=c+F(D,n);var=F(E,n)-F(D,n)**2
 quick('coded_totals',1,v,'Spread survives an origin shift',r'<p>For \(u=x-'+str(c)+r'\), n='+str(n)+r', \(\sum u='+str(D)+r'\), \(\sum u^2='+str(E)+r'\). Find the original mean, variance and SD exactly.</p>',[field('mean','Original mean','number',mu),field('variance','Original variance','number',var),field('sd','Original SD','number',sqrt(var))],'The coded mean need not be zero. Subtract its square in the variance formula; restore the origin only to the mean.',dict(kind='translation',n=n,D=D,E=E,c=c))
 n,D,E,a,b=(5,10,30,20,3) if v==0 else (4,8,24,20,-3);mu=a+b*F(D,n);var=b*b*(F(E,n)-F(D,n)**2)
 quick('coded_totals',2,v,'Decode spread through a scale',r'<p>For \(u=\frac{x-'+str(a)+'}{'+str(b)+r'}\), n='+str(n)+r', \(\sum u='+str(D)+r'\), \(\sum u^2='+str(E)+r'\). Find the original mean, variance and SD.</p>',[field('mean','Original mean','number',mu),field('variance','Original variance','number',var),field('sd','Original SD','number',sqrt(var))],'Write x=a+bu first. Variance uses b² and SD uses |b|.',dict(kind='affine',n=n,D=D,E=E,a=a,b=b))
 n,D,E,c,d=(5,-10,46,20,25) if v==0 else (6,12,40,50,47);h=d-c;var=F(E,n)-F(D,n)**2
 quick('coded_totals',3,v,'A new reference changes both coded totals',r'<p>n='+str(n)+r', \(\sum(x-'+str(c)+')='+str(D)+r'\), \(\sum(x-'+str(c)+')^2='+str(E)+r'\). Find the sum and square-total about '+str(d)+' and the unchanged SD.</p>',[field('sum','Sum about the new origin','number',D-n*h),field('squares','Square-total about the new origin','number',E-2*h*D+n*h*h),field('sd','Unchanged SD','number',sqrt(var))],'Expand (x−d)² with its cross-term and recheck that the variance is invariant.',dict(kind='recode',n=n,D=D,E=E,c=c,d=d))
 n,D,E,a,b=(4,6,14,10,2) if v==0 else (5,-5,15,30,-2);S=n*a+b*D;Q=n*a*a+2*a*b*D+b*b*E;var=F(Q,n)-F(S,n)**2
